{"message":"ご希望の有機的な装飾フレームを、XYに寝かせる単体パーツとして作成します。中央は開口のまま、四隅に非対称で先細りする曲線の蔓・炎状装飾を配置し、後で右上だけ差し替えられるよう部位を分けます。サイズは外接65×95×厚み12mm以内、色はマットな灰色に合わせます。前回の検証エラー（装飾が本体と体積で接続されておらず分離している）は、装飾パーツを背板と確実に重ねて結合することで修正します。これで問題なければ実装して追加します。適用してよければ承認してください。","changes":[{"path":"scene","value":"object"},{"path":"program.upsert","value":{"id":"model-1","name":"有機装飾フレーム（分割部位）","x":20,"y":20,"color":"#7A7A7A","size":[65,95,12],"source":"// Organic decorative frame for XY-facing placement
// Units: mm. Bounding box: 65 (X) × 95 (Y) × 12 (Z)
// Parts: tl (top-left), tr (top-right), bl (bottom-left), br (bottom-right)
// Backplate ensures all decorative elements are volumetrically connected to avoid separated pieces.
const back=box([61,91,4]);
// Top-left flourish (tl)
let tlPath=[];
tlPath.push([8,82,2]);
tlPath.push([6,72,4]);
tlPath.push([12,62,6]);
tlPath.push([20,54,8]);
tlPath.push([26,50,9]);
let tl=tube(tlPath,3.5);
// Top-right flourish (tr) — 独立部位として後で差し替え容易に
let trPath=[];
trPath.push([39,82,2]);
trPath.push([46,74,4]);
trPath.push([54,66,7]);
trPath.push([58,58,9]);
trPath.push([52,52,9]);
let tr=tube(trPath,3.5);
// Bottom-left flourish (bl)
let blPath=[];
blPath.push([8,12,2]);
blPath.push([10,22,4]);
blPath.push([16,32,6]);
blPath.push([24,40,8]);
blPath.push([30,44,9]);
let bl=tube(blPath,3.5);
// Bottom-right flourish (br)
let brPath=[];
brPath.push([39,12,2]);
brPath.push([46,22,5]);
brPath.push([54,34,7]);
brPath.push([58,42,9]);
brPath.push([50,48,9]);
let br=tube(brPath,3.5);
// Organic outer rim contour (XY outline). Center remains open — create rim as a thin extruded band
const outer=[[2,8],[8,6],[16,4],[26,4],[38,8],[48,12],[60,24],[62,36],[62,62],[58,78],[50,86],[40,90],[28,90],[16,86],[8,76],[2,64]];
const inner=[[22,30],[32,26],[44,28],[50,38],[50,56],[40,66],[30,70],[18,62]];
let rim=extrude(outer,4);
let hole=extrude(inner,4);
rim=subtract(rim,hole);
// Small droplets and bridges to create openings and organic feel
let drop1=tube([[34,48,4],[36,42,6],[32,38,8]],1.2);
let drop2=tube([[18,60,4],[22,54,6],[20,48,7]],1.0);
let bridge=tube([[28,34,4],[30,30,4],[34,32,5]],1.0);
// Ensure connections: move back slightly so rim and tubes overlap backplate volume
let frame=union(move(back,[2,2,0]),move(rim,[2,2,0]),move(tl,[2,2,0]),move(tr,[2,2,0]),move(bl,[2,2,0]),move(br,[2,2,0]),move(drop1,[2,2,0]),move(drop2,[2,2,0]),move(bridge,[2,2,0]));
// Final check: back 4mm + decorative max ~8mm = within 12mm thickness
return frame;"}},{"path":"name","value":"15cmぬいのおうち（オブジェクト：装飾フレーム追加）"}]}
